import { beforeEach, expect, test } from "/home/orangepi/Workspace/brews-bingo/backend/node_modules/vitest/dist/index.js";
import { env, exports } from "cloudflare:workers";
import { reset, runInDurableObject } from "cloudflare:test";
import { enroll, post, resetStorage, origin, cookie, inOwner } from "/home/orangepi/Workspace/brews-bingo/backend/worker-tests/fixtures.js";
const clock = Date.now;
const owner = id => env.GAMES.get(env.GAMES.idFromName(id));
const directory = () => env.GAME_DIRECTORY.get(env.GAME_DIRECTORY.idFromName("directory"));
beforeEach(async () => {
  Date.now = clock;
  await reset(); await resetStorage();
  await runInDurableObject(directory(), (_instance, state) => state.storage.deleteAll());
});
async function terminalFixture() {
  const host = await enroll("PonytailHistoryHost");
  const made = await post("/api/games", { configuration: { numeric_upper_bound: 4, board_side_length: 2, free_cells_enabled: false, free_cell_positions: [], player_capacity: 2, spectator_capacity: 0 } }, { session: host.session });
  expect(made.status).toBe(200);
  const id = (await made.json()).game.game_id;
  const opened = await post(`/api/games/${id}/lobby`, { expected_revision: 0 }, { session: host.session });
  expect(opened.status).toBe(200);
  const code = (await opened.json()).game_code;
  const sockets = [];
  for (const alias of ["First", "Second"]) {
    const context = await post(`/api/games/${id}/admission-context`, { game_code: code }, { id: null });
    expect(context.status).toBe(200);
    const joined = await post(`/api/games/${id}/players`, { game_code: code, alias }, { session: cookie(context) });
    expect(joined.status).toBe(200);
    const session = cookie(joined);
    await joined.text();
    const upgraded = await exports.default.fetch(`${origin}/api/games/${id}/stream?view=player`, { headers: { Cookie: session, Origin: origin, Upgrade: "websocket", Connection: "Upgrade" } });
    expect(upgraded.status).toBe(101);
    const ws = upgraded.webSocket;
    const first = new Promise(resolve => ws.addEventListener("message", event => {
      const frame = JSON.parse(event.data);
      if (frame.kind === "snapshot") {
        ws.send(JSON.stringify({ version: 1, kind: "snapshot_ack", connection_id: frame.connection_id, delivery_id: frame.delivery_id, view_revision: frame.view_revision }));
        resolve(frame);
      }
    }));
    ws.accept(); sockets.push(ws); await first;
  }
  const synced = await exports.default.fetch(`${origin}/api/games/${id}/sync?view=account`, { headers: { Cookie: host.session } });
  expect(synced.status).toBe(200);
  const revision = (await synced.json()).view_revision;
  expect((await post(`/api/games/${id}/start`, { expected_revision: revision }, { session: host.session })).status).toBe(200);
  expect((await post(`/api/games/${id}/cancel`, { confirmed: true, expected_state: "in_progress" }, { session: host.session })).status).toBe(200);
  const closed = sockets.map(ws => ws.readyState === 3 ? Promise.resolve() : new Promise(resolve => ws.addEventListener("close", resolve, { once: true })));
  for (const ws of sockets) ws.close(1000);
  await Promise.all(closed);
  return { id, host };
}

test("History final account expiry denial survives clock rollback", async () => {
  const f = await terminalFixture();
  const expiry = await inOwner((_instance, state) => state.storage.sql.exec("SELECT expires_at FROM account_sessions WHERE account_id=? AND scope='normal' AND revoked_at IS NULL", f.host.accountId).one().expires_at);
  Date.now = () => expiry - 1;
  await inOwner(instance => {
    instance.ponytailHistoryFetch = instance.fetch.bind(instance);
    instance.ponytailHistoryProofs = 0;
    instance.ponytailHistoryFences = 0;
    instance.fetch = async request => {
      const response = await instance.ponytailHistoryFetch(request.clone());
      if (new URL(request.url).pathname === "/game-authority" && (await request.clone().json()).action === "authorize") {
        ++instance.ponytailHistoryProofs;
        expect((await response.clone().json()).outcome.result).toBe("authorized");
        if (instance.ponytailHistoryProofs === 2) {
          let samples = 0;
          Date.now = () => ++samples === 1 ? expiry - 1 : expiry;
        }
      }
      if (new URL(request.url).pathname === "/game-authority" && (await request.clone().json()).action === "fence_expiry") ++instance.ponytailHistoryFences;
      return response;
    };
  });
  try {
    const denied = await owner(f.id).fetch("https://game.internal/history", { method: "POST", body: JSON.stringify({ game_id: f.id, token: f.host.session.split("=", 2)[1], summary: false }) });
    expect(denied.status).toBe(200);
    const outcome = (await denied.json()).outcome.result;
    expect(outcome).toBe("unauthorized");
    const floor = await runInDurableObject(owner(f.id), (_instance, state) => state.storage.sql.exec("SELECT last_observed_ms FROM game_metadata").one().last_observed_ms);
    const calls = await inOwner(instance => instance.ponytailHistoryProofs);
    const fences = await inOwner(instance => instance.ponytailHistoryFences);
    const accountFloor = await inOwner((_instance, state) => state.storage.sql.exec("SELECT last_observed_ms FROM storage_metadata WHERE singleton=1").one().last_observed_ms);
    expect(calls).toBe(2);
    await inOwner(instance => { instance.fetch = instance.ponytailHistoryFetch; delete instance.ponytailHistoryFetch; });
    Date.now = () => expiry - 1;
    const retried = await exports.default.fetch(`${origin}/api/history/${f.id}`, { headers: { Cookie: f.host.session } });
    console.log("PONYTAIL_HISTORY_EXPIRY", JSON.stringify({ expiry, game_floor_after_denial: floor, account_floor_after_denial: accountFloor, denied_outcome: outcome, proof_calls: calls, fences, rollback_at: Date.now(), fresh_public_status: retried.status }));
    await retried.text();
    expect([401, 503]).toContain(retried.status);
  } finally {
    Date.now = clock;
    await inOwner(instance => {
      if (instance.ponytailHistoryFetch) instance.fetch = instance.ponytailHistoryFetch;
      delete instance.ponytailHistoryFetch;
      delete instance.ponytailHistoryProofs;
      delete instance.ponytailHistoryFences;
    });
  }
});

