import { beforeEach, expect, test } from "/home/orangepi/Workspace/brews-bingo/backend/node_modules/vitest/dist/index.js";
import { env, exports } from "cloudflare:workers";
import { reset, runInDurableObject } from "cloudflare:test";
import { enroll, post, resetStorage, origin, cookie, password, commandId } from "/home/orangepi/Workspace/brews-bingo/backend/worker-tests/fixtures.js";

const clock = Date.now;
const owner = id => env.GAMES.get(env.GAMES.idFromName(id));
const directory = () => env.GAME_DIRECTORY.get(env.GAME_DIRECTORY.idFromName("directory"));
beforeEach(async () => {
  Date.now = clock;
  await reset(); await resetStorage();
  await runInDurableObject(directory(), (_instance, state) => state.storage.deleteAll());
});
async function fixture() {
  const base = clock();
  Date.now = () => base;
  const host = await enroll("PonytailCapHost");
  const made = await post("/api/games", {}, { session: host.session });
  expect(made.status).toBe(200);
  const id = (await made.json()).game.game_id;
  const opened = await post(`/api/games/${id}/lobby`, { expected_revision: 0 }, { session: host.session });
  expect(opened.status).toBe(200);
  const code = (await opened.json()).game_code;
  Date.now = () => base + 10000;
  const answer = password();
  const context = await post(`/api/games/${id}/admission-context`, { game_code: code }, { id: null });
  expect(context.status).toBe(200);
  const joined = await post(`/api/games/${id}/players`, { game_code: code, alias: "CapPlayer", recovery_answer: answer }, { session: cookie(context) });
  expect(joined.status).toBe(200);
  const session = cookie(joined);
  await joined.text();
  Date.now = () => base + 20000;
  return { id, code, answer, session, host };
}

for (const mode of ["recovery", "answer"]) {
  test(`original ${mode} output cap survives genuine host resume between owner cuts`, async () => {
    const f = await fixture();
    await runInDurableObject(owner(f.id), instance => {
      instance.ponytailOriginalFetch = instance.fetch.bind(instance);
      instance.ponytailCap = { first: null, second: null, resume: null, calls: 0 };
      instance.fetch = async request => {
        const body = new URL(request.url).pathname === "/command" ? await request.clone().json() : null;
        const response = await instance.ponytailOriginalFetch(request);
        if (body && response.status === 200 && ["recover_player", "recovery_output", "put_recovery_answer"].includes(body.operation)) {
          const reply = await response.clone().json();
          if (!["recovered", "recovery_answer"].includes(reply.owner_result)) return response;
          const probe = instance.ponytailCap;
          if (++probe.calls === 1) {
            probe.first = reply.valid_until;
            Date.now = () => probe.first - 1000;
            const resumed = await post(`/api/games/${f.id}/resume`, {}, { session: f.host.session });
            probe.resume = resumed.status;
            expect(resumed.status).toBe(200);
            await resumed.text();
          } else if (probe.calls === 2) {
            probe.second = reply.valid_until;
            Date.now = () => probe.first;
          }
        }
        return response;
      };
    });
    try {
      const response = mode === "recovery"
        ? await post("/api/games/player-recovery", { game_code: f.code, alias: "CapPlayer", recovery_answer: f.answer })
        : await exports.default.fetch(`${origin}/api/games/${f.id}/membership/recovery-answer`, {
            method: "PUT",
            headers: { Origin: origin, Cookie: f.session, "Content-Type": "application/json", "Idempotency-Key": commandId() },
            body: JSON.stringify({ recovery_answer: password() }),
          });
      const observed = await runInDurableObject(owner(f.id), instance => ({ ...instance.ponytailCap }));
      console.log("PONYTAIL_ORIGINAL_CAP", JSON.stringify({ mode, ...observed, observed_at: Date.now(), response_status: response.status, has_cookie: response.headers.has("set-cookie") }));
      expect(observed.calls).toBe(2);
      expect(observed.resume).toBe(200);
      expect(observed.second).toBeGreaterThan(observed.first);
      expect(Date.now()).toBe(observed.first);
      expect([401, 503]).toContain(response.status);
      expect(response.headers.has("set-cookie")).toBe(false);
    } finally {
      Date.now = clock;
      await runInDurableObject(owner(f.id), instance => {
        instance.fetch = instance.ponytailOriginalFetch;
        delete instance.ponytailOriginalFetch;
        delete instance.ponytailCap;
      });
    }
  });
}

