use super::super::tests::{authority, initialized};
use super::*;
use crate::auth::{
    AuthError,
    test_support::{Sqlite, TestRuntime},
};
use std::cell::RefCell;
use std::collections::VecDeque;

struct SampledClock<'a> {
    base: &'a TestRuntime,
    samples: RefCell<VecDeque<i64>>,
}
impl Runtime for SampledClock<'_> {
    fn now_ms(&self) -> i64 {
        self.samples
            .borrow_mut()
            .pop_front()
            .unwrap_or(self.base.now.get())
    }
    fn fill_random(&self, bytes: &mut [u8]) -> Result<(), AuthError> {
        self.base.fill_random(bytes)
    }
}

#[test]
fn ponytail_release_fences_actual_inner_expiry_sample() {
    let db = Sqlite::new();
    let rt = TestRuntime::new();
    initialized(&db, &rt);
    let svc = GameService::new(&db, &rt, AuthPolicy::default(), &[9; 32]).unwrap();
    let original = authority(&rt, 2);
    let account = GameAccountAuthority::from_trusted_peer(
        original.account_id(),
        original.session_id(),
        original.role(),
        original.credential_epoch(),
        rt.now.get() + 1000,
    )
    .unwrap();
    let selection = ReadSelection {
        game_id: svc.record().unwrap().id,
        kind: ReadKind::Game,
        role: ReadRole::Account,
        player_id: None,
    };
    let cut = svc
        .capture_read(selection, "", Some(&account), &[], false)
        .unwrap();
    let expiry = account.expires_at();
    rt.now.set(expiry - 1);
    let clock = SampledClock {
        base: &rt,
        samples: RefCell::new(VecDeque::from([expiry - 1, expiry])),
    };
    let sampled = GameService::new(&db, &clock, AuthPolicy::default(), &[9; 32]).unwrap();
    let denied = sampled.release_read(
        selection,
        "",
        Some(&account),
        &[],
        &cut.binding,
        &cut.projection,
    );
    assert_eq!(denied, Err(GameError::Unauthorized));
    let floor = number(
        &db.query("SELECT last_observed_ms FROM game_metadata", &[])
            .unwrap()[0],
        0,
    )
    .unwrap();
    let resumed = sampled
        .capture_read(selection, "", Some(&account), &[], false)
        .is_ok();
    println!(
        "PONYTAIL_RELEASE_CLOCK {{\"expiry\":{expiry},\"floor_after_denial\":{floor},\"rollback_at\":{},\"fresh_read_succeeded\":{resumed}}}",
        rt.now.get()
    );
    assert!(
        floor >= expiry,
        "The actual inner expiry observation must be durably fenced"
    );
    assert!(!resumed);
}

