test("recovery disconnect advances host revision for conditional sync", async () => {
  const host = await enroll("PonytailPresenceHost");
  const made = await post("/api/games", {}, { session: host.session });
  expect(made.status).toBe(200);
  const id = (await made.json()).game.game_id;
  const opened = await post(`/api/games/${id}/lobby`, { expected_revision: 0 }, { session: host.session });
  expect(opened.status).toBe(200);
  const code = (await opened.json()).game_code;
  const answer = password();
  const context = await post(`/api/games/${id}/admission-context`, { game_code: code }, { id: null });
  expect(context.status).toBe(200);
  const joined = await post(`/api/games/${id}/players`, { game_code: code, alias: "PresencePlayer", recovery_answer: answer }, { session: cookie(context) });
  expect(joined.status).toBe(200);
  const session = cookie(joined);
  await joined.text();
  const response = await exports.default.fetch(`${origin}/api/games/${id}/stream?view=player`, {
    headers: { Cookie: session, Origin: origin, Upgrade: "websocket", Connection: "Upgrade" },
  });
  expect(response.status).toBe(101);
  const ws = response.webSocket;
  const first = new Promise(resolve => ws.addEventListener("message", event => {
    const frame = JSON.parse(event.data);
    if (frame.kind === "snapshot") {
      ws.send(JSON.stringify({ version: 1, kind: "snapshot_ack", connection_id: frame.connection_id, delivery_id: frame.delivery_id, view_revision: frame.view_revision }));
      resolve(frame);
    }
  }));
  ws.accept(); await first;
  const sync = async query => {
    const r = await exports.default.fetch(`${origin}/api/games/${id}/sync?view=account${query}`, { headers: { Cookie: host.session } });
    expect(r.status).toBe(200);
    return r.json();
  };
  try {
    const before = await sync("");
    expect(before.snapshot.connected_player_count).toBe(1);
    const recovered = await post("/api/games/player-recovery", { game_code: code, alias: "PresencePlayer", recovery_answer: answer });
    expect(recovered.status).toBe(200);
    await recovered.text();
    const cached = await sync(`&known_revision=${before.view_revision}`);
    const full = await sync("");
    console.log("PONYTAIL_HOST_REVISION", JSON.stringify({ before_revision: before.view_revision, cached_revision: cached.view_revision, full_revision: full.view_revision, before_connected: before.snapshot.connected_player_count, after_connected: full.snapshot.connected_player_count, cached_up_to_date: cached.up_to_date, cached_snapshot_absent: cached.snapshot === null }));
    expect(full.snapshot.connected_player_count).toBe(0);
    expect(cached.up_to_date).toBe(false);
    expect(cached.view_revision).toBeGreaterThan(before.view_revision);
  } finally {
    ws.close(1000);
  }
});
